const categoryAvailable=(c,month='')=>c?.active!==false&&(!month||(!c.activeFrom||c.activeFrom<=month)&&(!c.inactiveFrom||month<c.inactiveFrom));
const topGroupOrder=['給料','生活費','固定費','NISA','別枠貯金','定期支出','特別収入','特別支出'];
