function renderReserve(){const rows=timeline(),cats=sortCategories(data.categories.filter(c=>c.active&&c.type==='reserve'&&c.scope!=='month'));if(!cats.length)return chartEmpty('reserveChart','別枠貯金の費目を追加すると表示します。');const balances=Object.fromEntries(cats.map(c=>[c.id,0])),snap=rows.map(r=>{const row=r.row||{month:r.month,status:'planned',values:{}};let contributions=cats.map(c=>actualBucketEntered(row,'purposeSaving')?n(value(row,c.id).actual):displayedPlanned(c,row)),allocated=contributions.reduce((s,v)=>s+v,0);if(cats.length&&allocated!==r.reserve)contributions[0]+=r.reserve-allocated;cats.forEach((c,i)=>balances[c.id]+=contributions[i]);return {...balances}}),max=Math.max(1,...snap.flatMap(s=>Object.values(s))),W=760,H=260,L=65,R=15,T=20,B=45,x=i=>L+i*(W-L-R)/Math.max(1,rows.length-1),y=v=>T+(max-v)/max*(H-T-B);$('reserveChart').innerHTML='<p class="hint">現金から別枠貯金へ移した累計です。合計資産は変わりません。</p><div class="chart-legend">'+cats.map((c,i)=>'<span><i style="background:'+palette[i%palette.length]+'"></i>'+esc(c.name)+'</span>').join('')+'</div><svg viewBox="0 0 '+W+' '+H+'"><text x="5" y="'+(T+4)+'" font-size="11">'+esc(yen(max))+'</text><text x="30" y="'+(H-B+4)+'" font-size="11">0円</text><line x1="'+L+'" x2="'+(W-R)+'" y1="'+(H-B)+'" y2="'+(H-B)+'" stroke="#79949e"/>'+cats.map((c,ci)=>'<polyline fill="none" stroke="'+palette[ci%palette.length]+'" stroke-width="3" points="'+rows.map((_,i)=>x(i)+','+y(snap[i][c.id]||0)).join(' ')+'"/>').join('')+rows.map((r,i)=>'<text x="'+x(i)+'" y="'+(H-14)+'" text-anchor="middle" font-size="11">'+r.month.slice(2)+'</text>').join('')+'</svg>'}
function homeRows(){const all=timeline(),selected=$('homeMonth')?.value||monthNow(),h=n($('homeHorizon')?.value||12);if(!h)return all;const ix=Math.max(0,all.findIndex(x=>x.month===selected));return all.slice(Math.max(0,ix-h),Math.min(all.length,ix+h+1))}
