function renderAssetOutlook(rows){if(!rows.length)return chartEmpty('assetOutlookChart','予定の月を追加すると表示します。');const vals=rows.flatMap(r=>[r.cash,r.invest,r.other,r.total]),min=Math.min(0,...vals),max=Math.max(1,...vals),W=820,H=320,L=72,R=18,T=20,B=48,x=i=>L+i*(W-L-R)/Math.max(1,rows.length-1),y=v=>T+(max-v)/(max-min||1)*(H-T-B),colors={cash:'#176f75',invest:'#3d78b8',other:'#8a6cb3',total:'#d67a39'};const lines=[['cash','現金・預金'],['invest','NISA・投資'],['other','別枠貯金'],['total','合計資産']],hit=Math.max(28,(W-L-R)/Math.max(1,rows.length));$('assetOutlookChart').innerHTML='<div class="chart-legend">'+lines.map(([k,l])=>'<span><i style="background:'+colors[k]+'"></i>'+l+'</span>').join('')+'</div><svg viewBox="0 0 '+W+' '+H+'" aria-label="資産推移"><text x="4" y="'+(T+5)+'" font-size="11">'+esc(yen(max))+'</text><text x="28" y="'+(y(0)+4)+'" font-size="11">0円</text>'+(min<0?'<text x="2" y="'+(H-B)+'" font-size="11">'+esc(yen(min))+'</text>':'')+'<line x1="'+L+'" x2="'+(W-R)+'" y1="'+y(0)+'" y2="'+y(0)+'" stroke="#78939b"/>'+lines.map(([k])=>'<polyline fill="none" stroke="'+colors[k]+'" stroke-width="3" points="'+rows.map((r,i)=>x(i)+','+y(r[k])).join(' ')+'"/>').join('')+rows.map((r,i)=>'<g><circle cx="'+x(i)+'" cy="'+y(r.total)+'" r="4" fill="'+colors.total+'"></circle><rect class="chart-hit" data-asset-month="'+r.month+'" tabindex="0" role="button" aria-label="'+r.month+'の資産内訳を見る" x="'+(x(i)-hit/2)+'" y="'+T+'" width="'+hit+'" height="'+(H-T-B)+'"></rect>'+(i%Math.max(1,Math.ceil(rows.length/10))===0?'<text x="'+x(i)+'" y="'+(H-14)+'" text-anchor="middle" font-size="11">'+r.month.slice(2)+'</text>':'')+'</g>').join('')+'</svg><div id="assetOutlookDetail" class="chart-detail asset-outlook-detail" aria-live="polite"><span>線や月に触れると、資産の内訳と計算元を表示します。</span></div>'}
function outlookCard(r){return '<details class="outlook-row"><summary><span><b>'+esc(r.month)+'</b><em class="status '+r.status+'">'+statusText(r.status)+'</em></span><strong class="'+signClass(r.netCash)+'">収支 '+signed(r.netCash)+'</strong><small>現金 '+yen(r.cash)+'　投資 '+yen(r.invest)+'　別枠 '+yen(r.other)+'　合計 '+yen(r.total)+'</small></summary><div class="outlook-grid"><span>収入 <b>'+yen(r.income)+'</b></span><span>支出（NISA除く） <b>'+yen(r.expense)+'</b></span><span>NISA・投資 <b>'+yen(r.investment)+'</b></span><span>別枠貯金 <b>'+yen(r.reserve)+'</b></span><span>現金増減 <b class="'+signClass(r.netCash)+'">'+signed(r.netCash)+'</b></span></div>'+(r.note?'<p class="hint">'+esc(r.note)+'</p>':'')+'<div class="actions"><button data-open-month="'+r.month+'">この月を記録</button><button data-open-plan="'+r.month+'">予定を編集</button></div></details>'}
function renderHome(){let all=timeline();if(!all.length){ensurePlanMonth(monthNow());all=timeline()}const select=$('homeMonth'),keep=select.value||monthNow();select.innerHTML=all.map(r=>'<option value="'+r.month+'">'+r.month+'（'+statusText(r.status)+'）</option>').join('');select.value=all.some(r=>r.month===keep)?keep:all.reduce((best,r)=>Math.abs(new Date(r.month+'-01')-new Date())<Math.abs(new Date(best.month+'-01')-new Date())?r:best,all[0]).month;const chosen=all.find(r=>r.month===select.value)||all[all.length-1],ix=all.indexOf(chosen),after=all[Math.min(all.length-1,ix+12)],saved=after?after.total-chosen.total:0;$('homeCards').innerHTML='<article><span>'+esc(chosen.month)+' の状態</span><strong>'+statusText(chosen.status)+'</strong><small>'+((chosen.status==='closed')?'入力した実績で計算':chosen.status==='draft'?'入力済み実績＋未入力の予定':'予定で計算')+'</small></article><article><span>月末の現金・預金</span><strong class="'+signClass(chosen.cash)+'">'+yen(chosen.cash)+'</strong></article><article><span>月末のNISA・投資</span><strong class="'+signClass(chosen.invest)+'">'+yen(chosen.invest)+'</strong></article><article><span>月末の別枠貯金</span><strong class="'+signClass(chosen.other)+'">'+yen(chosen.other)+'</strong></article><article><span>月末の合計資産</span><strong class="'+signClass(chosen.total)+'">'+yen(chosen.total)+'</strong></article><article><span>この月の現金増減</span><strong class="'+signClass(chosen.netCash)+'">'+signed(chosen.netCash)+'</strong></article><article><span>ここから12か月の資産増減</span><strong class="'+signClass(saved)+'">'+signed(saved)+'</strong></article>';const shown=homeRows();renderAssetOutlook(shown);$('outlookTable').innerHTML=shown.map(outlookCard).join('');stackedChart('categoryChart','expense','毎月の生活費の比較');renderReserve();$('homeNotice').innerHTML='<strong>見通しの作り方：</strong>「予定」で未来を入れ、「月の記録」で過ぎた月を実績確定すると、同じ表が予定から実績へ切り替わります。'}
const regularPlanCats=(month='')=>sortCategories(data.categories.filter(c=>categoryAvailable(c,month)&&c.scope!=='month'&&!isSpecialCategory(c)));
function plannedAt(c,month){if(!categoryAvailable(c,month))return 0;const row=data.months.find(m=>m.month===month),v=row?.values?.[c.id];if(v?.plannedOverride)return n(v.planned);const raw=categoryPlanAt(c,month);if(c.type!=='reserve')return v&&v.planned!==undefined?n(v.planned):raw;const cats=sortCategories(data.categories.filter(x=>categoryAvailable(x,month)&&x.scope!=='month'&&x.type==='reserve'));if(c.id!==cats[0]?.id)return raw;const aggregate=n(planFor(month).purposeSaving),allocated=cats.reduce((sum,x)=>sum+categoryPlanAt(x,month),0);return raw+aggregate-allocated}
function displayedPlanned(c,row){if(categoryBucket(c)==='nisa'&&(c.group==='NISA'||c.name==='NISA'))return n(planFor(row.month).nisa);if(c.type==='reserve')return plannedAt(c,row.month);return n(value(row,c.id).planned)}
function displayedActual(c,row){const v=value(row,c.id);return row.status==='closed'||v.actualEntered===true?n(v.actual):null}
function previousPlanMonth(month){return data.planMonths.map(x=>x.month).filter(x=>x<month).sort().at(-1)||''}
function categoryChanges(month){const prev=previousPlanMonth(month),cats=data.categories.filter(c=>c.active!==false&&c.scope!=='month'&&!isSpecialCategory(c));return cats.map(c=>({c,before:prev?plannedAt(c,prev):categoryAvailable(c,month)?n(c.defaultPlanned):0,after:plannedAt(c,month)})).filter(x=>x.before!==x.after)}
function changeText(x){const diff=x.after-x.before,word=diff>0?'増加':'減少';return categoryPath(x.c)+' '+yen(Math.abs(diff))+word}
const bucketLabel=c=>({salary:'収入',specialIncome:'特別収入',living:'生活費',fixed:'固定費',nisa:'NISA・投資',regular:'定期支出',specialExpense:'特別支出',purposeSaving:'別枠貯金'}[categoryBucket(c)]||'生活費');
function planItemHtml(c,r){return '<div class="plan-category-item" data-plan-category-row="'+c.id+'"><span><strong>'+esc(c.name)+'</strong><small class="plan-link">反映先：'+esc(bucketLabel(c))+'</small></span><label><span>予定額</span><span class="money-field"><input data-plan-category="'+c.id+'" data-money value="'+(plannedAt(c,r.month)||'')+'"><b>円</b></span></label><button type="button" class="danger small" data-end-plan-cat="'+c.id+'">この月以降は終了</button></div>'}
function planGroupBody(cs,r){const direct=cs.filter(c=>!c.subgroup).map(c=>planItemHtml(c,r)).join(''),subs=[...new Set(cs.map(c=>c.subgroup).filter(Boolean))];return subs.map(s=>{const rows=cs.filter(c=>c.subgroup===s),total=rows.reduce((sum,c)=>sum+plannedAt(c,r.month),0);return '<details class="plan-subgroup" data-subgroup="'+esc(s)+'"><summary><span>'+esc(s)+'</span><strong>'+yen(total)+'</strong></summary>'+rows.map(c=>planItemHtml(c,r)).join('')+'</details>'}).join('')+direct}
function planCategoryEditor(r){const cats=regularPlanCats(r.month),groups=sortGroups(new Set(cats.map(c=>c.group))),changes=categoryChanges(r.month),first=r.month===data.planMonths[0]?.month,summary=first?['基本の予定']:changes.length?changes.slice(0,3).map(changeText):['変更内容を入力'];return '<details class="plan-row" data-plan="'+r.month+'"><summary><span><b>'+esc(r.month)+'</b><em class="status planned">'+(first?'基本':'費目変更')+'</em></span><strong class="plan-change-summary">'+summary.map(x=>'<i class="change-chip">'+esc(x)+'</i>').join('')+(!first&&changes.length>3?'<i class="change-chip">ほか'+(changes.length-3)+'件</i>':'')+'</strong><small>'+(first?'予定の開始月':r.note?esc(r.note):changes.length+'件の変更')+'</small></summary><div class="plan-scope"><label>この画面で変更した金額<select data-plan-scope><option value="future">この月以降に反映</option><option value="only">この月だけ変更</option></select></label></div><div class="plan-category-groups">'+groups.map(g=>{const cs=cats.filter(c=>c.group===g),total=cs.reduce((s,c)=>s+plannedAt(c,r.month),0);return '<details class="plan-category-group" data-plan-group="'+esc(g)+'"><summary><span>'+esc(g)+'</span><strong>'+yen(total)+'</strong></summary>'+planGroupBody(cs,r)+'</details>'}).join('')+'</div><div class="actions"><button type="button" data-add-plan-cat="'+r.month+'">＋ この月から費目を追加</button></div><label>変更メモ<input data-plan-field="note" value="'+esc(r.note||'')+'" placeholder="例：転職、引っ越し、住民税の変更"></label><div class="actions"><button data-open-month="'+r.month+'">この月の実績を記録</button></div></details>'}
function refreshPlanMetrics(month){const box=document.querySelector('[data-plan="'+month+'"]'),r=data.planMonths.find(x=>x.month===month);if(!box||!r)return;const cats=regularPlanCats(month);box.querySelectorAll('.plan-subgroup[data-subgroup]').forEach(sub=>{const group=sub.closest('[data-plan-group]')?.dataset.planGroup||'',total=cats.filter(c=>c.group===group&&c.subgroup===sub.dataset.subgroup).reduce((sum,c)=>sum+plannedAt(c,month),0);directSummary(sub,'<span>'+esc(sub.dataset.subgroup)+'</span><strong>'+yen(total)+'</strong>')});box.querySelectorAll('[data-plan-group]').forEach(group=>{const name=group.dataset.planGroup,total=cats.filter(c=>c.group===name).reduce((sum,c)=>sum+plannedAt(c,month),0);directSummary(group,'<span>'+esc(name)+'</span><strong>'+yen(total)+'</strong>')});const changes=categoryChanges(month),first=month===data.planMonths[0]?.month,summary=first?['基本の予定']:changes.length?changes.slice(0,3).map(changeText):['変更内容を入力'];directSummary(box,'<span><b>'+esc(month)+'</b><em class="status planned">'+(first?'基本':'費目変更')+'</em></span><strong class="plan-change-summary">'+summary.map(x=>'<i class="change-chip">'+esc(x)+'</i>').join('')+(!first&&changes.length>3?'<i class="change-chip">ほか'+(changes.length-3)+'件</i>':'')+'</strong><small>'+(first?'予定の開始月':r.note?esc(r.note):changes.length+'件の変更')+'</small>')}
function planIsRegularChange(r,i){if(i===0)return true;if(categoryChanges(r.month).length)return true;return data.planRules.some(x=>x.startMonth===r.month&&!isSpecialCategory(data.categories.find(c=>c.id===x.categoryId)))}
function specialRows(){const rows=[];for(const s of data.plannedSpecials)rows.push({...s,legacy:false});for(const p of data.planMonths){for(const kind of ['income','expense']){const key=kind==='income'?'specialIncome':'specialExpense',known=data.plannedSpecials.filter(s=>s.month===p.month&&s.kind===kind).reduce((sum,s)=>sum+n(s.amount),0),rest=n(p[key])-known;if(rest)rows.push({id:'legacy:'+p.month+':'+kind,month:p.month,kind,name:kind==='income'?'特別収入（移行データ）':'特別支出（移行データ）',amount:rest,legacy:true})}}return rows.sort((a,b)=>a.month.localeCompare(b.month)||a.kind.localeCompare(b.kind))}
function renderSpecialRow(s){return '<details class="special-plan-row '+(s.legacy?'legacy':'')+'" data-special="'+s.id+'"><summary><b>'+esc(s.month)+'</b><span class="special-name">'+esc(s.name)+'</span><strong>'+yen(s.amount)+'</strong><span class="special-kind '+s.kind+'">'+(s.kind==='income'?'収入':'支出')+'</span></summary><div class="special-edit-grid"><label>年月<input type="month" data-special-edit="month" value="'+esc(s.month)+'"></label><label>名称<input data-special-edit="name" value="'+esc(s.name.replace('（移行データ）',''))+'"></label><label>種類<select data-special-edit="kind"><option value="expense" '+(s.kind==='expense'?'selected':'')+'>特別支出</option><option value="income" '+(s.kind==='income'?'selected':'')+'>特別収入</option></select></label><label><span>金額</span><span class="money-field"><input data-special-edit="amount" data-money value="'+n(s.amount)+'"><b>円</b></span></label></div><div class="actions"><button class="primary small" data-save-special="'+s.id+'">変更を保存</button><button class="danger small" data-delete-special="'+s.id+'">削除</button></div></details>'}
function renderPlan(openMonth=''){data.planMonths.sort((a,b)=>a.month.localeCompare(b.month));const changeRows=data.planMonths.filter((r,i)=>planIsRegularChange(r,i)||r.month===openMonth);$('planChangeRows').innerHTML=changeRows.length?changeRows.map(planCategoryEditor).join(''):'<div class="empty-plan">費目の変更予定はありません。</div>';const specials=specialRows();$('plannedSpecialRows').innerHTML=specials.length?specials.map(renderSpecialRow).join(''):'<div class="empty-plan">特別収入・特別支出の予定はありません。</div>';decorate();if(openMonth)requestAnimationFrame(()=>{const d=document.querySelector('[data-plan="'+openMonth+'"]');if(d)d.open=true})}
function changeSpecialTotal(s,direction){const p=ensurePlanMonth(s.month),key=s.kind==='income'?'specialIncome':'specialExpense';p[key]=Math.max(0,n(p[key])+direction*n(s.amount))}
function openSpecialDialog(id=''){const s=id?specialRows().find(x=>x.id===id):null;$('plannedSpecialTitle').textContent=s?'特別な予定を編集':'特別な予定を追加';$('plannedSpecialId').value=s?.id||'';$('plannedSpecialMonth').value=s?.month||monthNow();$('plannedSpecialKind').value=s?.kind||'expense';$('plannedSpecialName').value=s?.name?.replace('（移行データ）','')||'';$('plannedSpecialAmount').value=s?.amount||'';$('plannedSpecialDialog').showModal();decorate()}
function saveSpecialFromDialog(){const id=$('plannedSpecialId').value,month=$('plannedSpecialMonth').value,kind=$('plannedSpecialKind').value,name=$('plannedSpecialName').value.trim(),amount=n($('plannedSpecialAmount').value);if(!month||!name||!amount)return false;if(id){const old=specialRows().find(x=>x.id===id);if(old)changeSpecialTotal(old,-1);if(!id.startsWith('legacy:')){const current=data.plannedSpecials.find(x=>x.id===id);Object.assign(current,{month,kind,name,amount});changeSpecialTotal(current,1)}else{const created={id:uuid(),month,kind,name,amount};data.plannedSpecials.push(created);changeSpecialTotal(created,1)}}else{const created={id:uuid(),month,kind,name,amount};data.plannedSpecials.push(created);changeSpecialTotal(created,1)}save();return true}
function openCategoryDialog(startMonth=''){const groups=sortGroups(new Set(data.categories.filter(c=>c.active!==false&&c.scope!=='month').map(c=>c.group)));$('newGroup').innerHTML=groups.map(g=>'<option value="'+esc(g)+'">'+esc(g)+'</option>').join('')+'<option value="__new__">＋ 新しい大項目</option>';$('newGroupNameWrap').hidden=true;$('newGroupName').value='';$('newSubgroup').value='';$('newCategoryName').value='';$('newDefaultPlanned').value='';$('newCategoryStartMonth').value=startMonth;$('categoryDialogTitle').textContent=startMonth?startMonth+'から費目を追加':'基本の費目を追加';$('categoryDialogHint').textContent=startMonth?'追加した費目は'+startMonth+'以降の予定に表示されます。':'大項目、中項目、費目名の順で追加します。生活費の中項目には「食費」「交通費」などを入力できます。';$('categoryDialog').showModal();decorate()}

function moneyField(label,field,value){const shown=value===null||value===undefined||value===''?'':value;return '<label><span>'+label+'</span><span class="money-field"><input data-money data-field="'+field+'" value="'+shown+'"><b>円</b></span></label>'}
function detailsKey(d){return d.dataset.category?'item:'+d.dataset.category:d.dataset.group?'group:'+d.dataset.group:d.dataset.subgroup?'subgroup:'+d.dataset.subgroup:d.dataset.manage?'manage:'+d.dataset.manage:d.dataset.section?'section:'+d.dataset.section:''}
