function itemHtml(c,row){const v=value(row,c.id),planned=displayedPlanned(c,row),actual=displayedActual(c,row),diff=n(actual)-planned,has=!!String(v.comment||'').trim(),remove=c.scope==='month'?'<button type="button" class="danger small" data-remove-month-cat="'+c.id+'">この月から削除</button>':'<button type="button" class="danger small" data-remove-cat="'+c.id+'">この費目を削除</button>',rule=categoryBucket(c)==='nisa'?'実績が未入力なら予定額で計算し、実績を入力するとその月は実績額を優先します。空欄に戻すと予定額へ戻ります。':c.type==='reserve'?'入力額を現金から別枠貯金へ移します。現金は減りますが、合計資産は変わりません。':'';return '<details class="item" data-category="'+c.id+'"><summary><strong>'+esc(c.name)+'</strong><span>実績 '+(actual===null?'未入力':yen(actual))+'</span><small class="'+(actual===null?'':varianceClass(c.type,diff))+'">'+(actual===null?'予定 '+yen(planned):'予定差 '+signed(diff))+'</small></summary><div class="item-body grid"><label><span>費目名</span><input data-item-name value="'+esc(c.name)+'"></label>'+moneyField('実績','actual',actual===null?'':actual)+moneyField('予定','planned',planned)+'</div>'+(rule?'<p class="hint nisa-rule">'+rule+'</p>':'')+'<details class="comment-toggle"><summary>'+(has?'コメントあり・編集':'コメントを追加')+'</summary><input data-field="comment" value="'+esc(v.comment||'')+'" placeholder="任意"></details>'+remove+'</details>'}
function monthGroupBody(cs,row){const direct=cs.filter(c=>!c.subgroup).map(c=>itemHtml(c,row)).join(''),subs=[...new Set(cs.map(c=>c.subgroup).filter(Boolean))];return subs.map(s=>{const rows=cs.filter(c=>c.subgroup===s),actuals=rows.map(c=>displayedActual(c,row)),hasActual=actuals.some(v=>v!==null),actual=actuals.reduce((sum,v)=>sum+n(v),0),planned=rows.reduce((sum,c)=>sum+displayedPlanned(c,row),0),diff=actual-planned;return '<details class="subgroup" data-subgroup="'+esc(s)+'"><summary><strong>'+esc(s)+'</strong><span>実績 '+(hasActual?yen(actual):'未入力')+'</span><small class="'+(hasActual?varianceClass('expense',diff):'')+'">'+(hasActual?'予定差 '+signed(diff):'予定 '+yen(planned))+'</small></summary><div class="subgroup-body">'+rows.map(c=>itemHtml(c,row)).join('')+'</div></details>'}).join('')+direct}
function directSummary(el,html){const summary=[...el.children].find(x=>x.tagName==='SUMMARY');if(summary)summary.innerHTML=html}
function refreshMonthMetrics(row){const t=totals(row);$('monthSummary').innerHTML='<article><span>収入</span><strong>'+yen(t.income)+'</strong></article><article><span>支出</span><strong>'+yen(t.expense)+'</strong></article><article><span>収支</span><strong class="'+signClass(t.net)+'">'+signed(t.net)+'</strong></article>';const cats=visibleCats(row);document.querySelectorAll('#monthGroups [data-category]').forEach(item=>{const c=data.categories.find(x=>x.id===item.dataset.category);if(!c)return;const actual=displayedActual(c,row),planned=displayedPlanned(c,row),diff=n(actual)-planned;directSummary(item,'<strong>'+esc(c.name)+'</strong><span>実績 '+(actual===null?'未入力':yen(actual))+'</span><small class="'+(actual===null?'':varianceClass(c.type,diff))+'">'+(actual===null?'予定 '+yen(planned):'予定差 '+signed(diff))+'</small>')});document.querySelectorAll('#monthGroups .subgroup[data-subgroup]').forEach(box=>{const ids=[...box.querySelectorAll('[data-category]')].map(x=>x.dataset.category),rows=cats.filter(c=>ids.includes(c.id)),actuals=rows.map(c=>displayedActual(c,row)),hasActual=actuals.some(v=>v!==null),actual=actuals.reduce((sum,v)=>sum+n(v),0),planned=rows.reduce((sum,c)=>sum+displayedPlanned(c,row),0),diff=actual-planned;directSummary(box,'<strong>'+esc(box.dataset.subgroup)+'</strong><span>実績 '+(hasActual?yen(actual):'未入力')+'</span><small class="'+(hasActual?varianceClass('expense',diff):'')+'">'+(hasActual?'予定差 '+signed(diff):'予定 '+yen(planned))+'</small>')});document.querySelectorAll('#monthGroups .group[data-group]').forEach(box=>{const g=box.dataset.group,rows=cats.filter(c=>c.group===g),actuals=rows.map(c=>displayedActual(c,row)),hasActual=actuals.some(v=>v!==null),actual=actuals.reduce((sum,v)=>sum+n(v),0),planned=rows.reduce((sum,c)=>sum+displayedPlanned(c,row),0),diff=actual-planned;directSummary(box,'<strong>'+esc(g)+'</strong><span>実績 '+(hasActual?yen(actual):'未入力')+'</span><small class="'+(hasActual?varianceClass((g==='給料'||g==='特別収入')?'income':'expense',diff):'')+'">'+(hasActual?'予定差 '+signed(diff):'予定 '+yen(planned))+'</small>')})}
function renderMonth(){const open=openMonthDetails(),row=ensureMonth(activeMonth||monthNow());$('monthSelect').innerHTML=data.months.map(r=>'<option value="'+r.month+'" '+(r.month===row.month?'selected':'')+'>'+r.month+'（'+r.fiscalYear+'年度）</option>').join('');$('monthStatus').value=row.status||'draft';const t=totals(row);$('monthSummary').innerHTML='<article><span>収入</span><strong>'+yen(t.income)+'</strong></article><article><span>支出</span><strong>'+yen(t.expense)+'</strong></article><article><span>収支</span><strong class="'+signClass(t.net)+'">'+signed(t.net)+'</strong></article>';const cats=visibleCats(row),groups=sortGroups(new Set([...cats.map(c=>c.group),'特別収入','特別支出']));$('monthGroups').innerHTML=groups.map(g=>{const cs=cats.filter(c=>c.group===g),actuals=cs.map(c=>displayedActual(c,row)),hasActual=actuals.some(v=>v!==null),actual=actuals.reduce((sum,v)=>sum+n(v),0),planned=cs.reduce((sum,c)=>sum+displayedPlanned(c,row),0),diff=actual-planned,isSpecial=g==='特別収入'||g==='特別支出';return '<details class="group" data-group="'+esc(g)+'"><summary><strong>'+esc(g)+'</strong><span>実績 '+(hasActual?yen(actual):'未入力')+'</span><small class="'+(hasActual?varianceClass((g==='給料'||g==='特別収入')?'income':'expense',diff):'')+'">'+(hasActual?'予定差 '+signed(diff):'予定 '+yen(planned))+'</small></summary><div class="group-body">'+(g==='NISA'?'<p class="hint nisa-rule"><strong>NISAの計算：</strong>実績がなければ予定額、実績を入力した月は実績額を使います。</p>':g==='別枠貯金'?'<p class="hint nisa-rule"><strong>別枠貯金の計算：</strong>現金からこの貯金へ移します。実績がなければ予定、入力後は実績を使います。</p>':'')+(isSpecial?'<p class="hint">必要な月だけ費目を追加します。翌月には引き継がれません。</p>':'')+monthGroupBody(cs,row)+'<button class="small add-month-item" data-add-month-item="'+esc(g)+'">＋ '+(isSpecial?'この月の'+g:'この月だけの費目')+'を追加</button></div></details>'}).join('');$('cashBalance').value=row.balanceEntered&&row.balances?.cash!==null?row.balances.cash:'';$('investBalance').value=row.balanceEntered&&row.balances?.invest!==null?row.balances.invest:'';$('monthComment').value=row.comment||'';$('monthCommentSummary').textContent=row.comment?'この月全体のコメントあり・編集':'この月全体のコメントを追加';renderManager();decorate();restoreMonthDetails(open)}
function renderManager(){$('categoryManager').innerHTML=sortCategories(data.categories.filter(c=>c.active&&c.scope!=='month')).map(c=>'<details class="manager-entry" data-manage="'+c.id+'"><summary><strong>'+esc(categoryPath(c))+'</strong><small>標準予定 '+yen(c.defaultPlanned)+'</small></summary><div class="manager-row"><label>大項目<input data-cat="group" value="'+esc(c.group)+'"></label><label>中項目（任意）<input data-cat="subgroup" value="'+esc(c.subgroup||'')+'" placeholder="例：食費、交通費"></label><label>費目名<input data-cat="name" value="'+esc(c.name)+'"></label><label>種類<select data-cat="type"><option value="expense" '+(c.type==='expense'?'selected':'')+'>支出</option><option value="income" '+(c.type==='income'?'selected':'')+'>収入</option><option value="investment" '+(c.type==='investment'?'selected':'')+'>投資</option><option value="reserve" '+(c.type==='reserve'?'selected':'')+'>別枠貯金（用途別積立）</option></select></label><label><span>新しい月の標準予定額</span><span class="money-field"><input data-cat="defaultPlanned" data-money value="'+(c.defaultPlanned||'')+'"><b>円</b></span></label><button data-copy-cat="'+c.id+'">複製</button><button data-remove-cat="'+c.id+'" class="danger">削除</button></div></details>').join('')}

function analysisMonthDetail(month){const box=$('analysisTrendDetail'),row=data.months.find(r=>r.month===month),map=catMap(),chosen=(data.analysisSelection||[]).filter(id=>map[id]?.active);if(!box||!row)return;const items=chosen.map(id=>({c:map[id],v:n(value(row,id).actual)})).filter(x=>x.v!==0),total=items.reduce((s,x)=>s+x.v,0);box.innerHTML='<strong>'+esc(month)+'　合計 '+yen(total)+'</strong><div class="chart-detail-items">'+(items.length?items.map(x=>'<span>'+esc(x.c.group)+'／'+esc(x.c.name)+' '+yen(x.v)+'</span>').join(''):'<span>選択した費目の実績はありません。</span>')+'</div>'}
function renderAnalysisTrend(months,chosen){const rows=[...months].sort((a,b)=>a.month.localeCompare(b.month));if(!rows.length||!chosen.length)return chartEmpty('analysisTrend','費目を選ぶと月ごとの増減を表示します。');const vals=rows.map(r=>chosen.reduce((s,id)=>s+n(value(r,id).actual),0)),avg=vals.reduce((s,v)=>s+v,0)/vals.length,max=Math.max(10000,...vals,avg),W=760,H=285,L=65,R=14,T=20,B=47,x=i=>L+(i+.5)*(W-L-R)/rows.length,y=v=>T+(max-v)/max*(H-T-B),w=Math.max(8,Math.min(42,(W-L-R)/rows.length*.62));$('analysisTrend').innerHTML='<div class="chart-legend"><span><i style="background:#167e78"></i>月の実績</span><span><i style="background:#d67a39;height:3px"></i>期間平均</span></div><svg viewBox="0 0 '+W+' '+H+'" aria-label="生活費の月ごとの増減"><text x="5" y="'+(T+5)+'" font-size="11">'+esc(yen(max))+'</text><text x="30" y="'+(H-B+4)+'" font-size="11">0円</text><line x1="'+L+'" x2="'+(W-R)+'" y1="'+y(avg)+'" y2="'+y(avg)+'" stroke="#d67a39" stroke-width="3"/>'+rows.map((r,i)=>'<rect x="'+(x(i)-w/2)+'" y="'+y(vals[i])+'" width="'+w+'" height="'+Math.max(1,H-B-y(vals[i]))+'" fill="#167e78"></rect><rect class="chart-hit" data-analysis-month="'+r.month+'" tabindex="0" role="button" aria-label="'+r.month+'の内訳を見る" x="'+(x(i)-Math.max(w,28)/2)+'" y="'+T+'" width="'+Math.max(w,28)+'" height="'+(H-T-B)+'"></rect><text x="'+x(i)+'" y="'+(H-14)+'" text-anchor="middle" font-size="11">'+r.month.slice(2)+'</text>').join('')+'</svg><div id="analysisTrendDetail" class="chart-detail" aria-live="polite"><span>棒に触れると、その月の費目別内訳を表示します。</span></div>'}
function renderAnalysis(){const mode=$('averagePeriod').value;$('customPeriod').hidden=mode!=='custom';const months=selectedRows(mode),map=catMap(),available=regularExpenseCats(),chosen=(data.analysisSelection||[]).filter(id=>available.some(c=>c.id===id));$('analysisPicker').innerHTML=[...new Set(available.map(c=>c.group))].map(g=>'<details class="analysis-group"><summary>'+esc(g)+'</summary><label><input type="checkbox" data-pick-group="'+esc(g)+'">この大項目をまとめて選ぶ</label>'+available.filter(c=>c.group===g).map(c=>'<label><input type="checkbox" data-pick="'+c.id+'" '+(chosen.includes(c.id)?'checked':'')+'>'+esc([c.subgroup,c.name].filter(Boolean).join('／'))+'</label>').join('')+'</details>').join('');const count=Math.max(1,months.length),avg=id=>({p:months.reduce((s,m)=>s+n(value(m,id).planned),0)/count,a:months.reduce((s,m)=>s+n(value(m,id).actual),0)/count});let p=0,a=0;chosen.forEach(id=>{const v=avg(id);p+=v.p;a+=v.a});const monthly=months.map(m=>({month:m.month,total:chosen.reduce((s,id)=>s+n(value(m,id).actual),0)})),low=monthly.reduce((best,x)=>!best||x.total<best.total?x:best,null),high=monthly.reduce((best,x)=>!best||x.total>best.total?x:best,null),spread=(high?.total||0)-(low?.total||0);$('analysisCards').innerHTML='<article><span>月平均</span><strong>'+yen(a)+'</strong></article><article><span>最も少ない月</span><strong>'+yen(low?.total||0)+'</strong><small>'+esc(low?.month||'―')+'</small></article><article><span>最も多い月</span><strong>'+yen(high?.total||0)+'</strong><small>'+esc(high?.month||'―')+'</small></article><article><span>月ごとの振れ幅</span><strong>'+yen(spread)+'</strong></article><article><span>予定平均との差</span><strong class="'+(a>p?'negative':'positive')+'">'+signed(a-p)+'</strong></article>';renderAnalysisTrend(months,chosen);$('averageTable').innerHTML='<table><thead><tr><th>費目</th><th>予定平均</th><th>実績平均</th><th>差</th></tr></thead><tbody>'+chosen.map(id=>{const c=map[id],v=avg(id);return '<tr><th>'+esc(categoryPath(c))+'</th><td>'+yen(v.p)+'</td><td>'+yen(v.a)+'</td><td class="'+(v.a>v.p?'negative':'positive')+'">'+signed(v.a-v.p)+'</td></tr>'}).join('')+'</tbody></table>';const gs={};chosen.forEach(id=>{const c=map[id],v=avg(id);gs[c.group]||={p:0,a:0};gs[c.group].p+=v.p;gs[c.group].a+=v.a});$('groupAverageTable').innerHTML='<table><thead><tr><th>大項目</th><th>予定平均</th><th>実績平均</th></tr></thead><tbody>'+Object.entries(gs).map(([g,v])=>'<tr><th>'+esc(g)+'</th><td>'+yen(v.p)+'</td><td>'+yen(v.a)+'</td></tr>').join('')+'</tbody></table>';const variable=chosen.map(id=>{const vals=months.map(m=>n(value(m,id).actual));return {c:map[id],range:vals.length?Math.max(...vals)-Math.min(...vals):0}}).sort((x,y)=>y.range-x.range)[0];let advice='<p>固定費・食費など、毎月の生活費だけを集計します。特別支出・特別収入・投資・別枠貯金は含めません。</p>';if(chosen.length&&months.length>1){advice+='<p>最も支出が多い<strong>'+esc(high.month)+'</strong>は、平均より<strong>'+yen(high.total-a)+'</strong>多い月です。'+(variable?.range?'<strong>'+esc(variable.c.name)+'</strong>は月による差が'+yen(variable.range)+'あり、増えた理由を確認する候補です。':'')+'</p>';advice+=a<p?'<p>実績平均は予定より<strong>'+yen(p-a)+'</strong>少ないため、同じ傾向が続くなら月の予定額を下げられる可能性があります。</p>':a>p?'<p>実績平均は予定より<strong>'+yen(a-p)+'</strong>多いため、予定額の不足か一時的な増加かを確認してください。</p>':'<p>実績平均と予定平均は同程度です。</p>'}else if(chosen.length)advice+='<p>2か月以上記録すると、月ごとの振れ幅と増えた費目を比較できます。</p>';else advice+='<p>「比較する生活費を選ぶ」から確認したい生活費を選んでください。</p>';$('insights').innerHTML=advice;if(data.forecast?.length){$('forecastBox').hidden=false;$('forecastTable').innerHTML='<table><thead><tr><th>年月</th><th>給料</th><th>特別収入</th><th>生活費</th><th>固定費</th><th>NISA</th><th>定期支出</th><th>特別支出</th></tr></thead><tbody>'+data.forecast.slice(0,120).map(x=>'<tr><td>'+esc(x.month)+'</td>'+['salary','specialIncome','living','fixed','nisa','regular','specialExpense'].map(k=>'<td>'+yen(x[k])+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}else $('forecastBox').hidden=true}
function renderSource(){const s=data.sourceInfo;$('sourceInfo').innerHTML=s?.sheets?.length?'<p><strong>'+esc(s.fileName||'家計簿.xlsx')+'</strong>から'+s.sheets.length+'シートを取り込みました。</p><ul>'+s.sheets.map(x=>'<li>'+esc(x.name)+'：'+n(x.nonEmptyCells)+'セル</li>').join('')+'</ul><p class="hint">全シートの元データは移行ファイル内にも残しています。</p>':'<p>Excelからの移行データはまだ読み込まれていません。</p>'}
function renderProfiles(){const select=$('bookProfileSelect');if(!select)return;select.innerHTML=profiles.map(p=>'<option value="'+p.id+'" '+(p.id===activeProfileId?'selected':'')+'>'+esc(p.name||'家計簿')+'</option>').join('');$('deleteProfile').disabled=profiles.length<=1}
function loadProfile(id){const found=profiles.find(x=>x.id===id);if(!found)return;save();activeProfileId=id;localStorage.setItem(ACTIVE_PROFILE_KEY,id);try{data=migrate(JSON.parse(localStorage.getItem(profileKey(id))))}catch{data=fresh();data.name=found.name||'家計簿'}if(!data.months.length)ensureMonth(monthNow());activeMonth=data.months[0].month;render()}
function addProfile(name,copyCurrent=false){const clean=String(name||'').trim();if(!clean)return;const next=copyCurrent?migrate(JSON.parse(JSON.stringify(data))):fresh(),id=uuid();next.name=clean;next.updatedAt=new Date().toISOString();profiles.push({id,name:clean,updatedAt:next.updatedAt});activeProfileId=id;data=next;localStorage.setItem(ACTIVE_PROFILE_KEY,id);if(!data.months.length)ensureMonth(monthNow());else save();activeMonth=data.months[0].month;render()}
function removeActiveProfile(){if(profiles.length<=1)return;const current=profiles.find(x=>x.id===activeProfileId);if(!confirm('保存先「'+(current?.name||'家計簿')+'」と、その中のデータを削除しますか？'))return;localStorage.removeItem(profileKey(activeProfileId));profiles=profiles.filter(x=>x.id!==activeProfileId);activeProfileId=profiles[0].id;localStorage.setItem(PROFILE_INDEX_KEY,JSON.stringify(profiles));localStorage.setItem(ACTIVE_PROFILE_KEY,activeProfileId);try{data=migrate(JSON.parse(localStorage.getItem(profileKey(activeProfileId))))}catch{data=fresh()}if(!data.months.length)ensureMonth(monthNow());activeMonth=data.months[0].month;render()}
function render(){const page=document.querySelector('.page.active')?.id;$('bookTitle').textContent=data.name||'家計簿';$('bookName').value=data.name||'家計簿';renderProfiles();if(page==='home')renderHome();if(page==='plan')renderPlan();if(page==='month')renderMonth();if(page==='analysis')renderAnalysis();if(page==='data')renderSource();decorate()}
function download(name,obj){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function linkExport(){const period=n($('linkPeriod').value),rows=selectedRows(period),cats=catMap(),months=rows.map(r=>{const items=Object.entries(r.values||{}).map(([id,v])=>({categoryId:id,group:cats[id]?.group||'',subgroup:cats[id]?.subgroup||'',name:cats[id]?.name||'',type:cats[id]?.type||'expense',planned:n(v.planned),actual:n(v.actual),comment:v.comment||''}));const t=totals(r);return {month:r.month,fiscalYear:fiscal(r.month),income:t.income,living:t.expense,investment:t.investment,purposeSaving:t.reserve,net:t.net,cashBalance:n(r.balances?.cash),investBalance:n(r.balances?.invest),comment:r.comment||'',items}});return {format:'jp.household.actuals',schemaVersion:4,exportedAt:new Date().toISOString(),categories:data.categories.map(({id,group,subgroup,name,type,defaultPlanned})=>({id,group,subgroup:subgroup||'',name,type,defaultPlanned})),periodMonths:period||months.length,months}}
